sealed interface Employee permits FullTime,Contract{String name();double pay();}record FullTime(String name,double monthlySalary)implements Employee{public double pay(){return monthlySalary;}}record Contract(String name,int hours,double rate)implements Employee{public double pay(){return hours*rate;}}class Main{public static void main(String[] args){java.util.List<Employee> staff=java.util.List.of(new FullTime("Asha",50000),new Contract("Ravi",80,500));for(Employee employee:staff)System.out.println(employee.name()+" "+employee.pay());}}
